DNSResult processDNSResponse() {
    // Assume receiving DNS response into buffer (simplified for example)
    uint8_t buffer[512];
    ssize_t received = recv(socket_fd, buffer, sizeof(buffer), 0);
    if (received < 0) {
        return DNSResult{"", "", 0, "", "Failed to receive DNS response"};
    }

    // Check if the full header was received
    if (received < sizeof(DNSHeader)) {
        return DNSResult{"", "", 0, "", "Incomplete DNS header received"};
    }

    DNSHeader* header = reinterpret_cast<DNSHeader*>(buffer);
    if (header->qr != 1) { // Not a response
        return DNSResult{"", "", 0, "", "Received a DNS query instead of response"};
    }

    // Check if the response ID matches a pending request
    auto it = pending_requests.find(ntohs(header->id));
    if (it == pending_requests.end()) {
        return DNSResult{"", "", 0, "", "DNS response ID does not match any pending request"};
    }

    // Validate source of the response
    sockaddr_in server_address;
    socklen_t server_address_len = sizeof(server_address);
    if (getpeername(socket_fd, reinterpret_cast<sockaddr*>(&server_address), &server_address_len) < 0) {
        return DNSResult{"", "", 0, "", "Failed to get DNS server address"};
    }

    if (server_address.sin_addr.s_addr != expected_dns_server_ip) {
        return DNSResult{"", "", 0, "", "DNS response from an unexpected server"};
    }

    // Process the DNS response data based on query type (A, AAAA, CNAME, PTR)
    DNSAnswer answer;
    if (!parseDNSAnswer(buffer, received, answer)) {
        return DNSResult{"", "", 0, "", "Failed to parse DNS answer"};
    }

    DNSResult result;
    result.id = std::to_string(ntohs(header->id));
    result.response_data = answer.data;
    result.ttl = answer.ttl;
    result.original_request = it->second;

    pending_requests.erase(it); // Remove the request from the pending list

    return result;
}

