DNSResult processDNSResponse() {
    // Receive the DNS response
    DNSHeader header = receiveDNSHeader();
    if (!header.isComplete()) {
        return DNSResult::error("Incomplete DNS header received");
    }

    // Validate the source
    if (!validateDNSSource(header.getServerIP())) {
        return DNSResult::error("Response from invalid DNS server");
    }

    // Check if the response ID matches a pending request
    DNSRequest* request = findPendingRequest(header.getId());
    if (!request) {
        return DNSResult::error("No matching pending request found");
    }

    // Process the response data based on query type
    std::string result;
    switch (request->getQueryType()) {
        case QueryType::A:
            result = processARecord(header.getARecord());
            break;
        case QueryType::AAAA:
            result = processAAAARecord(header.getAAAARecord());
            break;
        case QueryType::CNAME:
            result = processCNAMERecord(header.getCNAMERecord());
            break;
        case QueryType::PTR:
            result = processPTRRecord(header.getPTRRecord());
            break;
        default:
            return DNSResult::error("Unsupported query type");
    }

    // Construct and return the DNSResult object
    return DNSResult(
        header.getId(),
        result,
        header.getTTL(),
        request->getRequestInfo()
    );
}

DNSResult processDNSResponse() {
    DNSHeader header;
    char buffer[DNS_BUFFER_SIZE];
    sockaddr_in sourceAddress;
    int addressLength = sizeof(sourceAddress);

    // Receive the DNS response
    int bytesReceived = recvfrom(socketFd, buffer, sizeof(buffer), 0,
                                 (sockaddr *)&sourceAddress, &addressLength);
    if (bytesReceived <= 0) {
        return DNSResult::error("Failed to receive DNS response");
    }

    // Check if the full header was received
    if (bytesReceived < sizeof(DNSHeader)) {
        return DNSResult::error("Incomplete DNS header received");
    }

    std::memcpy(&header, buffer, sizeof(DNSHeader));
    if (!header.isValid()) {
        return DNSResult::error("Invalid DNS header");
    }

    // Check if the response matches the expected DNS server
    if (!isExpectedDNSServer(sourceAddress)) {
        return DNSResult::error("Response from unexpected DNS server");
    }

    // Check if the response ID matches a pending request
    auto it = pendingRequests.find(header.id);
    if (it == pendingRequests.end()) {
        logError("DNS response ID does not match any pending request", header.id);
        return DNSResult::error("No matching request found for response");
    }

    DNSRequestInfo requestInfo = it->second;
    pendingRequests.erase(it);

    // Process response data based on query type
    std::string responseData;
    if (requestInfo.queryType == QType::A) {
        responseData = parseARecord(buffer + sizeof(DNSHeader), bytesReceived - sizeof(DNSHeader));
    } else if (requestInfo.queryType == QType::AAAA) {
        responseData = parseAAAARecord(buffer + sizeof(DNSHeader), bytesReceived - sizeof(DNSHeader));
    } else if (requestInfo.queryType == QType::CNAME) {
        responseData = parseCNAMERecord(buffer + sizeof(DNSHeader), bytesReceived - sizeof(DNSHeader));
    } else if (requestInfo.queryType == QType::PTR) {
        responseData = parsePTRRecord(buffer + sizeof(DNSHeader), bytesReceived - sizeof(DNSHeader));
    } else {
        return DNSResult::error("Unsupported query type");
    }

    if (responseData.empty()) {
        return DNSResult::error("Failed to parse DNS response data");
    }

    // Construct and return DNSResult
    DNSResult result;
    result.id = header.id;
    result.responseData = responseData;
    result.ttl = header.ttl;
    result.originalRequest = requestInfo;

    return result;
}
